public class Foo {
    void direct() throws Exception {
        try {
            throw new Exception();
        } catch (Exception e) {
            throw e;
        }
    }
    void cleanup(java.util.List<String> pending) throws Exception {
        try {
            throw new Exception();
        } catch (Exception e) {
            pending.clear();
            throw e;
        }
    }
    void logging() throws Exception {
        try {
            throw new Exception();
        } catch (Exception e) {
            e.printStackTrace();
            throw e;
        }
    }
    void nestedBlocks() throws Exception {
        try {
            throw new Exception();
        } catch (Exception e) {
            {
                {
                    throw e;
                }
            }
        }
    }
}

public class Foo {
    void wrapped() {
        try {
            throw new Exception();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}

public class Foo {
    void full(boolean condition) throws Exception {
        try {
            throw new Exception();
        } catch (Exception e) {
            if (condition) {
                throw e;
            } else {
                throw e;
            }
        }
    }
    void partial(boolean condition) throws Exception {
        try {
            throw new Exception();
        } catch (Exception e) {
            if (condition) {
                throw e;
            }
        }
    }
}

public class Foo {
    void earlyReturn(boolean condition) throws Exception {
        try {
            throw new Exception();
        } catch (Exception e) {
            if (condition) {
                return;
            }
            throw e;
        }
    }
}

public class Foo {
    void nestedTryFinally() throws Exception {
        try {
            throw new Exception();
        } catch (Exception e) {
            try {
                throw e;
            } finally {
                cleanup();
            }
        }
    }
    void cleanup() {
    }
}

public class Foo {
    void swallowed() throws Exception {
        try {
            throw new java.io.IOException();
        } catch (Exception e) {
            try {
                throw e;
            } catch (java.io.IOException ignored) {
                // The original exception is swallowed by this non-configured catch type.
            }
        }
    }
}

public class Foo {
    void innerOnly() throws Exception {
        try {
            throw new Exception();
        } catch (Exception e) {
            try {
                throw new RuntimeException();
            } catch (RuntimeException inner) {
                throw inner;
            }
        }
    }
}

