    void throwable() throws Throwable {
        try {
            throw new Throwable();
        } catch (Throwable e) {
            log(e);
            throw e;
        }
    }
    void error() throws Error {
        try {
            throw new Error();
        } catch (Error e) {
            log(e);
            throw e;
        }
    }
    void log(Object value) {
    }
}

