    void multiCatch() throws Exception {
        try {
            throw new Exception();
        } catch (Exception | Error e) {
            log(e);
            throw e;
        }
    }
    void log(Object value) {
    }
}

public class Foo {
    void independent() throws Exception {
        try {
            throw new Exception();
        } catch (Exception e) {
            throw e;
