        }
    }
}

package custom;
public class Foo {
    void customType() throws FooException {
        try {
            throw new FooException();
        } catch (FooException e) {
            throw new RuntimeException(e);
        }
    }
    void customRethrow() throws FooException {
        try {
            throw new FooException();
        } catch (FooException e) {
            throw e;
        }
    }
}
class FooException extends Exception {
}

public class Foo {
    void reassigned() throws Exception {
        try {
            throw new Exception();
        } catch (Exception e) {
            e = new Exception();
            throw e;
        }
    }
}

public class Foo {
    void nestedDeclarations() throws Exception {
        try {
            throw new Exception();
        } catch (Exception e) {
            java.util.concurrent.Callable<Void> lambda = () -> { throw e; };
            class Local {
                void run() throws Exception {
                    throw e;
                }
            }
            new Local().run();
        }
    }
}

class Foo {
    void returning(boolean condition) throws Exception {
        try { throw new Exception(); }
        catch (Exception e) {
            try {
                throw e;
            } finally {
                if (condition) {
                    return;
                }
            }
        }
    }
    void replacing() throws Exception {
        try { throw new Exception(); }
        catch (Exception e) {
            try {
                throw e;
            } finally {
                throw new IllegalStateException(e);
            }
        }
    }
}

class Foo {
    void partial(boolean condition) throws Exception {
        try { throw new Exception(); }
        catch (Exception | Error e) {
            if (condition) {
                throw e;
            }
        }
    }
}

class Foo {
    void remainingPaths(boolean condition) throws Exception {
        try { throw new Exception(); }
        catch (Exception e) {
            if (condition) {
                throw e;
            }
            throw (e);
        }
    }
    void nestedCleanup() throws Exception {
        try { throw new Exception(); }
        catch (Exception e) {
            try {
                cleanup();
            } catch (IllegalStateException cleanupFailure) {
                e.addSuppressed(cleanupFailure);
            }
            throw e;
        }
    }
    void cleanup() { }
}

class Foo {
    Exception e = new Exception();
    void field() throws Exception {
        try { throw new Exception(); }
        catch (Exception e) {
            throw this.e;
        }
    }
    void other(Exception other) throws Exception {
        try { throw new Exception(); }
        catch (Exception e) {
            throw other;
        }
    }
}
